import SwiftUI

@main
struct InspectorProbeApp: App {
    var body: some Scene {
        WindowGroup { RootView() }
    }
}

struct RootView: View {
    @State private var tab = 1

    var body: some View {
        TabView(selection: $tab) {
            Tab("Robot", systemImage: "figure.wave", value: 1) { pane("ROBOT") }
            Tab("Live", systemImage: "cube.transparent", value: 2) { pane("LIVE") }
            Tab("Moves", systemImage: "music.note", value: 3) { pane("MOVES") }
            Tab("Apps", systemImage: "square.grid.2x2", value: 4) { pane("APPS") }
            Tab("Settings", systemImage: "gearshape", value: 5) { pane("SETTINGS") }
        }
        .tabViewStyle(.sidebarAdaptable)
        .inspector(isPresented: .constant(true)) {
            GeometryReader { g in
                ZStack {
                    Color.green
                    VStack(spacing: 6) {
                        Text("INSPECTOR").font(.headline)
                        Text("\(Int(g.size.width)) x \(Int(g.size.height))")
                            .font(.system(.title3, design: .monospaced))
                        Text("safe t\(Int(g.safeAreaInsets.top)) b\(Int(g.safeAreaInsets.bottom))")
                            .font(.system(.caption, design: .monospaced))
                    }
                    .foregroundStyle(.black)
                }
            }
            .ignoresSafeArea()
        }
        .inspectorColumnWidth(min: 260, ideal: 380, max: 640)
    }

    func pane(_ title: String) -> some View {
        NavigationStack {
            GeometryReader { g in
                ZStack {
                    Color.blue.opacity(0.25)
                    VStack(spacing: 6) {
                        Text(title).font(.headline)
                        Text("content \(Int(g.size.width)) x \(Int(g.size.height))")
                            .font(.system(.title3, design: .monospaced))
                    }
                }
            }
            .navigationTitle(title)
        }
    }
}

