import Observation
import ReachyDesign
import SwiftUI

/// Where the one live view of the robot is drawn, and the geometry of the window
/// that carries it off the Live tab.
///
/// **`placement` is derived, never assigned.** `LiveTab` draws the viewport only
/// at `.inline` and the overlay only at everything else, so the two predicates
/// come out of a single value and there is no state in which both are true. That
/// is what keeps `ReachyScene/AGENTS.md`'s "move the view; never mount two" true
/// by construction rather than by review — an `Entity` has one parent, and a
/// second `RealityView` would silently take the robot from the first.
///
/// The gesture's starting values are stored properties rather than
/// `@GestureState`, which is the shape `OrbitCamera` already uses and the only one
/// in this project.
///
/// **Two placements are in play while anything is moving, and the split is the whole
/// design.** `drawn` is where the geometry is heading and `placement` is what is
/// mounted — they differ for exactly as long as an animation runs. Keeping them apart
/// is what lets the window morph on **one** SwiftUI identity: two `switch` branches
/// returning structurally different views have different identities, and nothing
/// geometric can interpolate across an identity boundary, so `withAnimation` was left
/// with only the default opacity transition to run. It is also what moves the
/// RealityKit teardown out of the animation: see `settling`.
@MainActor
@Observable
final class FloatingViewportModel {
    /// What a finished drag carries: where the finger was *heading*, never where it
    /// stopped. A flick and a haul end in the same place and mean different things, and
    /// the finger that was set down needs no second point — at rest SwiftUI predicts
    /// where it already is, so one value answers both.
    ///
    /// It comes straight off `DragGesture.Value` and is still measured from the touch,
    /// so the model subtracts its own `activation` — a caller must not do it twice.
    struct DragRelease {
        let predictedEndTranslation: CGSize
    }

    /// Where the window sits whenever the tab does not have it. Never `.inline` —
    /// that case belongs to `placement`, which is what merges this with the two
    /// inputs below.
    private(set) var rest: Placement = .floating(.bottomTrailing)

    /// Whether the shell is showing a tab bar rather than a sidebar. Written by
    /// the modifier that mounts the overlay, because that is the one place the
    /// size class is read.
    ///
    /// False collapses everything back to today's behaviour: the viewport is the
    /// tab's, always, and `isStreaming` is never true — so a sidebar layout cannot
    /// leave a stream running behind a screen that is not showing it.
    var hasTabBar = false

    /// Whether the Live tab is the selected one. Written by the shell.
    var isLiveTabSelected = false

    /// Whether the window is offered at all — the only one of `placement`'s four
    /// inputs that outlives the app.
    ///
    /// **The gesture is not half of this switch.** Throwing the window at an edge
    /// answers "get out of the way for a minute" and leaves a tab saying how to get
    /// it back; this answers "do not offer it". Off collapses `placement` to
    /// `.inline` — the shape a sidebar layout already had, which is why nothing in
    /// `RootLifecycle` needs to know it exists.
    private(set) var isEnabled: Bool

    /// Whether the running-app strip is on screen. Written by the shell, because
    /// neither placement the strip can take is reported to the overlay's safe area —
    /// the system's accessory slot is invisible to it for the same reason the tab
    /// bar is, and the fallback's inset sits *inside* a tab, one level further in
    /// than the overlay can see.
    var hasBottomAccessory = false

    /// Set while the window grows to fill the screen, in the instant before the
    /// tab takes the viewport over. There is no matched transition to be had here
    /// — that would need both hosts alive at once — so the overlay animates its
    /// own frame and hands the content over only once it is done.
    private(set) var isExpanding = false

    /// Where the window is heading while an animation runs, and `nil` at rest.
    ///
    /// **This is what keeps RealityKit out of the animation.** Assigning `rest`
    /// directly took `isStreaming` false in the same runloop turn the animation
    /// started, and `RootLifecycle` answers that synchronously with
    /// `viewport.setActive(false)` → `pauseStream()` on the main actor — a stall
    /// landing on the frames the animation was trying to draw. The geometry follows
    /// `drawn`, so it can leave immediately; `rest` waits for `finishSettling()`.
    ///
    /// The two directions want the wait for opposite reasons, and both get it:
    /// docking keeps the renderer mounted while it fades, undocking keeps the stream
    /// off until the window has finished growing, so the picture appears in a window
    /// that has already arrived.
    private(set) var settling: Placement?

    /// How far the finger has carried the window since the gesture woke up. A pure
    /// function of the gesture — nothing about the screen is captured when it begins,
    /// so a rectangle that changes mid-drag re-clamps and cannot drift, and a gesture
    /// SwiftUI drops without an `onEnded` leaves nothing behind but this one value.
    private(set) var dragTranslation: CGSize = .zero

    /// The translation SwiftUI reported the moment it woke the recogniser up. It is
    /// never zero: `minimumDistance` means the first `onChanged` already carries
    /// everything the finger travelled before the gesture existed — 4 pt at the very
    /// least, and arbitrarily more from a fast finger. Subtracting it is what stops
    /// the window teleporting by a speed-dependent amount at every touch-down.
    private var activation: CGSize?

    private let preferences: FloatingViewportPreferences

    init(preferences: FloatingViewportPreferences = FloatingViewportPreferences()) {
        self.preferences = preferences
        isEnabled = preferences.isEnabled
    }

    var placement: Placement {
        isLiveTabSelected || !hasTabBar || !isEnabled ? .inline : rest
    }

    /// The placement the geometry draws: where an animation in flight is heading, and
    /// the real one otherwise. Inline out-votes both — the overlay is not on screen at
    /// all while the tab has the viewport.
    var drawn: Placement {
        guard !isInline else { return .inline }
        return settling ?? placement
    }

    /// The window's size at rest in whichever placement is being drawn. The content
    /// inside keeps `Metrics.floatingViewport` and is clipped by this, so the
    /// renderer's own frame never moves and the morph costs no layout.
    var drawnSize: CGSize {
        switch drawn {
        case .inline, .floating: Metrics.floatingViewport
        case .docked: Metrics.viewportTab
        }
    }

    /// The edge the drawn shape is flush with, and `nil` where it is flush with
    /// nothing. Feeds `Radius.flush(to:_:)`, which is what squares off the two corners
    /// that meet the screen.
    var drawnEdge: HorizontalEdge? {
        if case let .docked(edge, _) = drawn {
            edge
        } else {
            nil
        }
    }

    /// Whether the tab owns the viewport. The overlay draws exactly when this is
    /// false, and `LiveTab` exactly when it is true.
    var isInline: Bool {
        placement == .inline
    }

    /// The one thing `RootLifecycle` asks: is anything outside the Live tab
    /// keeping the stream alive? A docked window is the off switch, so it is not.
    var isStreaming: Bool {
        if case .floating = placement {
            true
        } else {
            false
        }
    }

    // MARK: - Placement

    /// The switch on the Live tab, and the only writer of `isEnabled`.
    ///
    /// **Coming back lands in a corner, never where the window was left.** `rest`
    /// remembers one that was thrown at an edge, and restoring a 44 pt tab is
    /// indistinguishable from a switch that does nothing — which is the very
    /// complaint this exists to answer, wearing a different hat.
    func setEnabled(_ enabled: Bool) {
        guard isEnabled != enabled else { return }
        isEnabled = enabled
        preferences.isEnabled = enabled
        if enabled {
            rest = .floating(.bottomTrailing)
        }
    }

    /// The window was tapped: grow it, then let the caller select the tab. Split
    /// in two so the model never has to know what a `router` is.
    func beginExpanding() {
        isExpanding = true
    }

    func endExpanding() {
        isExpanding = false
    }

    /// Starts switching the window off at an edge, keeping the height it was at. The
    /// one lever the user has over the stream, and the reason `isStreaming` exists.
    ///
    /// Only the geometry moves here. `finishSettling()` is what stops the stream, and
    /// the caller owes it that call from the animation's completion handler.
    func beginDocking(_ edge: HorizontalEdge, in bounds: CGRect) {
        guard case .floating = rest, settling == nil else { return }
        settling = .docked(edge, y: Self.clampedTabY(centre(in: bounds).y, in: bounds))
    }

import ReachyDesign
import ReachyKit
import ReachyMedia
import SwiftUI

/// The viewport, full screen on every platform.
///
/// Teleop already lives here — `CameraViewport` hangs `JoystickPad` off the
/// factory this passes down — so the full controller belongs behind this tab's
/// bar rather than two taps deep in a `Form` on another one.
struct LiveTab: View {
    let session: RobotSession
    let viewport: ViewportModel
    let floating: FloatingViewportModel
    let router: ReachyRouter
    let remoteLink: RemoteRobotLink?

    /// The one record of what this robot was last asked for, and it lives here because
    /// this tab is where both readers are: the Presence sheet inside the viewport, and
    /// the two joysticks that turn those behaviours off when a hand takes the head.
    /// `ViewportView` used to own it, which lost the record every time a sleeping robot
    /// or the floating window unmounted that view.
    @State private var presence = PresenceModel()

    var body: some View {
        @Bindable var router = router
        return NavigationStack {
            // No `ignoresSafeArea` here. It used to be the joystick's bottom
            // safe-area inset that ruled it out; the joystick is an overlay now, and
            // the reason survives the change intact — an overlay is bounded by the
            // rectangle it is applied to, so a viewport reaching past the safe area
            // would put the pad and the recentre button under the tab bar. Full-bleed
            // video is a separate decision, and it has to answer what the glass bar
            // renders once the picture passes beneath it.
            content
                .navigationTitle(.reachy("Live"))
                .hfAccountToolbar(isPresented: $router.showsAccount)
                .toolbar {
                    if session.canTeleoperate {
                        ToolbarItem {
                            NavigationLink {
                                ControllerScreen(
                                    session: session,
                                    standDown: presence.teleopStandDown(session: session)
                                )
                            } label: {
                                Label(.reachy("Controller"), systemImage: "gamecontroller")
                            }
                        }
                    }
                    if floating.hasTabBar {
                        ToolbarItem { optionsMenu }
                    }
                }
        }
    }

    /// The switch for the floating window, and the reason it is here rather than in
    /// Settings: this is the screen the window belongs to, and it is the one screen
    /// guaranteed to be reachable in both states — off makes every placement
    /// `.inline`, so the tab draws the viewport and carries this toolbar either way.
    ///
    /// Behind `hasTabBar` because the window does not exist without one. A sidebar
    /// keeps Live beside every other destination, so there is nothing to float and
    /// nothing to switch off; the flag is read off the model rather than from
    /// `horizontalSizeClass`, which keeps the target's one size-class branch its
    /// only one.
    ///
    /// A menu rather than a bare icon: the complaint that led here was that the
    /// only way to put the window away could not be found, and what is found is a
    /// word, not a glyph.
    private var optionsMenu: some View {
        Menu {
            Toggle(.reachy("Mini window"), isOn: Binding(
                get: { floating.isEnabled },
                set: { floating.setEnabled($0) }
            ))
        } label: {
            Label(.reachy("Live options"), systemImage: "pip")
        }
    }

    /// Both streams would keep working while the robot sleeps — the camera hangs
    /// off `get_daemon` and the state stream off a running backend — but working is
    /// not the same as worth having. A motionless pose and a still frame cost the
    /// robot's radio and this phone's battery to show nothing, and a switcher
    /// between two inert views is a control that leads nowhere. So the tab keeps
    /// its place and offers the one thing that changes the situation.
    @ViewBuilder
    private var content: some View {
        if viewportTarget == nil {
            LiveUnavailableView()
        } else if session.isAwake {
            if floating.isInline {
                ViewportView(
                    model: viewport,
                    offersCamera: session.hasCamera,
                    makeTeleop: makeTeleop,
                    robotSession: session,
                    presence: presence
                )
            } else {
                // The shell builds all five tabs at once, so this body runs while
                // another tab is showing — and that is exactly when the floating
                // window holds the viewport. Drawing anything live here would be
                // the second `RealityView` the whole design exists to prevent.
                Color.clear
            }
        } else {
            // Pinned to the top: the banner is the tab's only content, and a lone
            // card floating in the middle of an empty screen reads as a view that
            // failed to load rather than as a status about the robot.
            AsleepBanner(session: session)
                .padding()
                .frame(maxWidth: 420)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        }
    }

    private var viewportTarget: ViewportModel.Source? {
        RootViewportTarget.source(session: session, remoteLink: remoteLink)
    }

    /// Absent where this connection carries no teleop, so the joystick is not
    /// offered rather than offered inert.
    private var makeTeleop: TeleopFactory? {
        guard session.canTeleoperate else { return nil }
        return { [session] in try session.makeTeleop() }
    }
}

import ReachyDesign
import ReachyKit
import ReachyMedia
import SwiftUI

/// The connected interface: five tabs that are always there.
///
/// `.sidebarAdaptable` is iOS 18 / macOS 15 — on the deployment floor, not an
/// iOS 26 API — and it replaces the hand-written `HStack { viewport | Divider |
/// column }` the root used to build for a regular width. Five unconditional tabs
/// are what make it possible: a sidebar cannot adapt around a destination that
/// appears and disappears under it.
struct ReachyTabShell: View {
    let session: RobotSession
    let viewport: ViewportModel
    let floating: FloatingViewportModel
    let runningApp: RunningAppModel
    let router: ReachyRouter
    let remoteLink: RemoteRobotLink?
    let findRobot: () -> Void

    /// The store's two models live here rather than inside the Apps tab because the
    /// dock expands into the *same* page a store row opens, and it does so from
    /// every tab. One copy, or the two surfaces disagree about what is installed the
    /// moment either one acts. They are inert until `load()`, so holding them for
    /// the life of a connection costs nothing — and a connection is exactly how long
    /// the caches behind them live.
    @State private var store: AppStoreModel
    @State private var install: AppInstallModel

    init(
        session: RobotSession,
        viewport: ViewportModel,
        floating: FloatingViewportModel,
        runningApp: RunningAppModel,
        router: ReachyRouter,
        remoteLink: RemoteRobotLink?,
        findRobot: @escaping () -> Void
    ) {
        self.session = session
        self.viewport = viewport
        self.floating = floating
        self.runningApp = runningApp
        self.router = router
        self.remoteLink = remoteLink
        self.findRobot = findRobot
        _store = State(initialValue: AppStoreModel(session: session))
        _install = State(initialValue: AppInstallModel(session: session))
    }

    var body: some View {
        @Bindable var router = router
        return TabView(selection: $router.tab) {
            Tab(value: ReachyRouter.Tab.robot) {
                docked {
                    RobotTab(session: session, router: router)
                }
            } label: {
                Label(.reachy("Robot"), systemImage: "figure.wave")
            }
            Tab(value: ReachyRouter.Tab.live) {
                docked {
                    LiveTab(
                        session: session,
                        viewport: viewport,
                        floating: floating,
                        router: router,
                        remoteLink: remoteLink
                    )
                }
            } label: {
                Label(.reachy("Live"), systemImage: "cube.transparent")
            }
            Tab(value: ReachyRouter.Tab.moves) {
                docked {
                    MovesTab(session: session, router: router)
                }
            } label: {
                Label(.reachy("Moves"), systemImage: "music.note")
            }
            Tab(value: ReachyRouter.Tab.apps) {
                docked {
                    AppsTab(
                        session: session,
                        router: router,
                        runningApp: runningApp,
                        store: store,
                        install: install,
                        findRobot: findRobot
                    )
                }
            } label: {
                Label(.reachy("Apps"), systemImage: "square.grid.2x2")
            }
            Tab(value: ReachyRouter.Tab.settings) {
                docked {
                    SettingsTab(session: session, router: router)
                }
            } label: {
                Label(.reachy("Settings"), systemImage: "gearshape")
            }
        }
        .tabViewStyle(.sidebarAdaptable)
        // The strip lives in the system's accessory slot, which is the row a
        // minimised bar shrinks to make. Order against `floatingViewport` is free —
        // measured on iOS 26.4, an accessory applied either side of the overlay
        // reports the same geometry to the point.
        .reachyTabAccessory(isPresented: dockIsUp) { dock }
        // The bar gets out of the way while reading a list and comes back on the way
        // up. iPhone only, and the fork lives in `ReachyChrome` — a sidebar has
        // nothing to minimise. It used to be switched off while the dock was up,
        // for a reason the accessory removes; `reachyMinimizingTabBar` carries it.
        .reachyMinimizingTabBar()
        // The router is read here rather than inside the model: `placement` is a
        // function of which tab is showing, and this is the one place that knows.
        .onChange(of: router.tab, initial: true) { _, tab in
            floating.isLiveTabSelected = tab == .live
        }
        // Neither placement the strip can take is reported to an overlay on the
        // `TabView`, the way the tab bar is not, so the window is told rather than
        // left to measure.
        .onChange(of: dockIsUp, initial: true) { _, isUp in
            floating.hasBottomAccessory = isUp
        }
        .floatingViewport(model: floating, viewport: viewport, session: session) {
            router.tab = .live
        }
        // Not mounted in the gate: with no connection `RunningAppModel.canPoll` is
        // false and the dock draws nothing, so the polling should die with the shell
        // rather than idle behind the gate.
        .runningApp(session: session, model: runningApp, store: store, install: install)
    }

    private var dockIsUp: Bool {
        runningApp.visibleStatus(for: session) != nil
    }

    /// The strip, wherever it is drawn. One definition, six mount points, of which
    /// exactly one is live on any given OS.
    private var dock: some View {
        RunningAppDock(session: session, model: runningApp)
    }

    /// Below iOS 26.1, and on every macOS, the inset belongs to the **tab**: on the
    /// `TabView` a bottom `safeAreaInset` is drawn straight over the bar, and on a
    /// tab's content it lands above it. A no-op wherever the system slot is live, so
    /// the two can never both draw a strip.
    ///
    /// Five copies of the strip therefore exist below the floor, since the shell
    /// builds all five tabs at once. That is layout only — every effect the dock has
    /// lives in `runningApp`, mounted once — so do not collapse these into a single
    /// overlay on the `TabView`: an overlay does not inset a tab's content, and the
    /// last row of every list would sit under the strip forever.
    private func docked(@ViewBuilder _ content: () -> some View) -> some View {
        content().reachyTabAccessoryFallback(isPresented: dockIsUp) { dock }
    }
}

