/// The single value all three hosts read. There is no state in which the tab, the
/// overlay and the column would each draw a viewport, because there is nothing to
/// disagree about — which is what keeps a second `RealityView` off the screen.
///
/// **It used to compare two predicates that were each other's negation**, so the
/// first expectation held for any input at all and certified nothing. With a third
/// host that is no longer even the right shape: the count is what has to be one.
@Test("exactly one of the three hosts draws")
func exactlyOneHost() {
    let rests: [FloatingViewportModel.Placement] = [
        .floating(.topLeading),
        .floating(.bottomTrailing),
        .docked(.leading, y: 200),
        .docked(.trailing, y: 600),
    ]
    for rest in rests {
        for hasTabBar in [true, false] {
            for live in [true, false] {
                for enabled in [true, false] {
                    let model = FloatingViewportModel.preview(
                        rest,
                        hasTabBar: hasTabBar,
                        isLiveTabSelected: live,
                        isEnabled: enabled
                    )
                    let hosts = [model.isInline, model.isWindowed, model.placement == .column]
                    let drawing = hosts.filter { $0 }.count
                    #expect(drawing == 1)
                    #expect(model.isInline == (model.placement == .inline))
                    #expect(!(model.isStreaming && model.isInline))
                }
            }
        }
    }
}

