127	    /// **The one derived value, and the whole of the "one at a time" guarantee.**
128	    /// Two inputs send the viewport back to the tab — it is showing, or the reader
129	    /// switched the second place off — and `hasTabBar` then picks which second place
130	    /// it is. `rest` is the window's own corner or edge and is never consulted for a
131	    /// column, which has neither.
132	    var placement: Placement {
133	        if isLiveTabSelected || !isEnabled { return .inline }
134	        return hasTabBar ? rest : .column
135	    }
136	
137	    /// The placement the geometry draws: where an animation in flight is heading, and
138	    /// the real one otherwise.
139	    ///
140	    /// **It answers only for the overlay, so it collapses both non-window placements
141	    /// to `.inline`.** The overlay is not mounted at all while the tab or the column
142	    /// has the viewport, and `.column` has no corner, no edge and no size of its own —
143	    /// the inspector decides its width. That is what keeps `drawnSize` and `drawnEdge`
144	    /// window arithmetic rather than a switch with a meaningless fourth answer in it.
145	    var drawn: Placement {
146	        guard isWindowed else { return .inline }
147	        return settling ?? placement
148	    }
149	
150	    /// The window's size at rest in whichever placement is being drawn. The content
151	    /// inside keeps `Metrics.floatingViewport` and is clipped by this, so the
152	    /// renderer's own frame never moves and the morph costs no layout.
153	    var drawnSize: CGSize {
154	        switch drawn {
155	        case .inline, .column, .floating: Metrics.floatingViewport
156	        case .docked: Metrics.viewportTab
157	        }
158	    }
159	
160	    /// The edge the drawn shape is flush with, and `nil` where it is flush with
161	    /// nothing. Feeds `Radius.flush(to:_:)`, which is what squares off the two corners
162	    /// that meet the screen.
163	    var drawnEdge: HorizontalEdge? {
164	        if case let .docked(edge, _) = drawn {
165	            edge
166	        } else {
167	            nil
168	        }
169	    }
170	
171	    /// Whether the tab owns the viewport. `LiveTab` draws exactly when this is true.
