/// **This asserted the opposite until the column existed**, on the reasoning that
/// a sidebar keeps the Live tab beside everything else and so has nothing to float.
/// True of a window and false of the viewport: a sidebar has width to spare, so the
/// viewport leaves the tab as a column instead of not leaving at all. The stream
/// runs with it, which is the half the old test was right to care about — a column
/// is on screen beside every other tab, so nothing is running behind a screen that
/// is not showing it.
@Test("no tab bar puts the viewport in a column, streaming")
func regularWidthUsesTheColumn() {
    let model = model(.floating(.topLeading), hasTabBar: false)

    #expect(model.placement == .column)
    #expect(model.isStreaming)
    #expect(!model.isInline)
    #expect(!model.isWindowed)
}

/// `rest` is the window's own memory — a corner, or an edge it was thrown at — and
/// a column has neither. A sidebar must therefore reach the same placement whatever
/// the window was last doing, or rotating an iPad would land the reader somewhere
/// that depends on a gesture made in the other orientation.
@Test("a column ignores where the window was left")
func columnIgnoresRest() {
    let rests: [FloatingViewportModel.Placement] = [
        .floating(.topLeading),
        .floating(.bottomTrailing),
        .docked(.leading, y: 200),
        .docked(.trailing, y: 600),
    ]
    for rest in rests {
        #expect(model(rest, hasTabBar: false).placement == .column)
    }
}

/// Switched off under a sidebar is the one state that still behaves the way this
/// target did before either second place existed — which is what the switch is for.
@Test("switched off, a sidebar hands the viewport back to the tab")
func disabledSidebarIsInline() {
    let model = FloatingViewportModel.preview(
        .floating(.topLeading),
        hasTabBar: false,
        isEnabled: false
    )

    #expect(model.placement == .inline)
    #expect(model.isInline)
    #expect(!model.isStreaming)
}

