/// **This asserted `.inline` and no stream until the column existed**, on the
/// reasoning that a sidebar has nothing to float. True of a window, false of the
/// viewport: a sidebar has width to spare, so it leaves the tab rather than stays.
///
/// The loop is the second half: `rest` is the window's own memory and a column has
/// neither corner nor edge, so a sidebar must reach the same placement whatever the
/// window was last doing — or rotating an iPad would land the reader somewhere
/// decided by a gesture made in the other orientation.
@Test("no tab bar puts the viewport in a column, whatever the window was doing")
func regularWidthUsesTheColumn() {
    let rests: [FloatingViewportModel.Placement] = [
        .floating(.topLeading),
        .floating(.bottomTrailing),
        .docked(.leading, y: 200),
        .docked(.trailing, y: 600),
    ]
    for rest in rests {
        let model = model(rest, hasTabBar: false)
        #expect(model.placement == .column)
        #expect(model.isStreaming)
        #expect(!model.isInline)
        #expect(!model.isWindowed)
    }
}

