// below stays empty until it happens.
#Preview("Root — idle, signed in") {
    PreviewScene.root(
        .preview(phase: .idle, status: nil, address: nil),
        hfAccount: PreviewScene.account(in: .signedIn(username: "alexey1312"))
    )
