private var framedBounds: BoundingBox?

/// Width ÷ height of the view this camera renders into, so `frame(_:)` can back off
/// far enough for the **narrower** of the two fields of view rather than always for
/// the vertical one.
///
/// It shipped without this and the robot was cropped down its sides in the trailing
/// column — 280 pt wide against 1210 tall, where width is the limiting dimension by
/// a factor of four. Nothing was wrong with the old number: `2.2` is exactly
/// `1 / sin(30°) · 1.1`, which fits a sphere into a 60° vertical field with 10 % to
/// spare, and every host before the column was wider than it was tall.
public var aspect: Float = 1 {
    didSet {
        guard aspect != oldValue, let framedBounds else { return }
        frame(framedBounds)
    }
}

/// RealityKit's default vertical field of view.
private static let verticalFieldOfView: Float = 60 * .pi / 180

/// How far back a sphere of `radius` has to be seen whole at this aspect.
///
/// **At every aspect ≥ 1 this returns the old `radius * 2.2` exactly**, because the
/// horizontal field is then the wider one and the vertical governs — which is why
/// adopting it moved no reference image and changed neither the full-screen viewport
/// nor the 160 × 112 floating window. It only ever pulls back, and only for a host
/// taller than it is wide.
static func distance(radius: Float, aspect: Float) -> Float {
    let vertical = verticalFieldOfView
    let horizontal = 2 * atan(tan(vertical / 2) * max(aspect, 0.01))
    return radius / sin(min(vertical, horizontal) / 2) * 1.1
}

