file.content:
    /// **The old constant is the new formula's answer at every aspect ≥ 1**, which is
    /// what made adopting it safe: `2.2` is `1 / sin(30°) · 1.1`, the distance that
    /// fits a sphere into a 60° vertical field with a tenth to spare, and a host wider
    /// than it is tall is limited by that vertical field whatever its width. Every
    /// viewport before the trailing column was in that half of the range.
    @Test("a viewport wider than it is tall keeps the framing it always had")
    func wideAspectsAreUnchanged() {
        let aspects: [Float] = [1, 1.43, 2, 16.0 / 9]
        for aspect in aspects {
            #expect(abs(OrbitCamera.distance(radius: 1, aspect: aspect) - 2.2) < 1e-4)
        }
    }

    /// The column is 280 pt wide against 1210 tall, where width is the limiting
    /// dimension by a factor of four — and the robot was cropped down both sides until
    /// the camera was told so.
    @Test("a viewport taller than it is wide backs the camera off")
    func tallAspectsPullBack() {
        let square = OrbitCamera.distance(radius: 1, aspect: 1)
        var previous = square
        let aspects: [Float] = [0.75, 0.5, 0.25]
        for aspect in aspects {
            let pulled = OrbitCamera.distance(radius: 1, aspect: aspect)
            #expect(pulled > previous)
            previous = pulled
        }
        // Narrower than the robot is tall means backing off by more than the width ratio
        // alone: at a quarter the width the sphere still has to clear a quarter-width
        // field, which is further than four radii.
        #expect(OrbitCamera.distance(radius: 1, aspect: 0.25) > square * 3)
    }

    /// A drag on the divider changes the column's width while the scene is mounted, so
    /// the framing has to follow rather than be decided once when the robot arrives.
    @Test("changing the aspect re-frames a camera that has already framed")
    func aspectReframesInPlace() {
        let camera = OrbitCamera()
        camera.frame(robotBounds)
        let wide = simd_distance(camera.entity.position(relativeTo: nil), robotBounds.center)

        camera.aspect = 0.25
        let narrow = simd_distance(camera.entity.position(relativeTo: nil), robotBounds.center)

        #expect(narrow > wide)
    }
}

